function leerVault() {
  // El texto lo resuelve el nodo "Extraer el texto", pero ese nodo se queda
  // SOLO con la clave que le pides y tira el resto del json, el nombre del
  // fichero incluido. Hay que ir a buscarlo al nodo de lectura, que saca los
  // items en el mismo orden, y emparejarlos por posicion.
  const leidos = $('Leer el vault').all();
  const ficheros = [];
  $input.all().forEach((item, i) => {
    const j = item.json ?? {};
    if (typeof j.contenido !== 'string' || !j.contenido) return;
    const src = leidos[i] ?? {};
    const nombre = src.json?.fileName ?? src.binary?.data?.fileName;
    // Sin nombre no se puede ni marcar el fichero ni citarlo: mejor saltarlo
    // que escribir en un sitio inventado.
    if (!nombre) return;
    ficheros.push({ nombre, texto: j.contenido });
  });
  return ficheros;
}

function frontmatter(texto) {
  // Un parser de YAML de tres lineas. Solo hay que leer lo que escribe
  // "Componer nota", que son pares clave: valor planos.
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function chatPermitido() {
  // En un chat privado el chat_id es tu propio user id, asi que no hace falta
  // guardarlo en ningun sitio: ya esta en el entorno desde la fase 1.
  const c = $env.TELEGRAM_ALLOWED_USER_ID;
  if (!c) throw new Error('TELEGRAM_ALLOWED_USER_ID no esta definido en el contenedor de n8n');
  return Number(c);
}

function marcarAvisado(texto) {
  if (/^avisado:/m.test(texto)) {
    return texto.replace(/^avisado:.*$/m, 'avisado: true');
  }
  // Nota anterior a la fase 4, sin el campo. Si no se lo metemos, no hay forma
  // de marcarla y te avisaria cada quince minutos para siempre.
  return texto.replace(/^---\r?\n([\s\S]*?)\r?\n---/,
    (m, cuerpo) => '---\n' + cuerpo + '\navisado: true\n---');
}

// Modo: Run Once for All Items.
// El parte de las 8:00. Un solo mensaje, siempre: un resumen que calla cuando
// no hay nada no se distingue de un bot roto.

const chat = chatPermitido();
const ahora = DateTime.now().setZone('Europe/Madrid');
const inicioHoy = ahora.startOf('day');
const finHoy = ahora.endOf('day');
const finSemana = ahora.plus({ days: 7 }).endOf('day');

const eventos = [];
for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  if (!fm.cuando) continue;
  const d = DateTime.fromISO(fm.cuando, { zone: 'Europe/Madrid' });
  if (!d.isValid || d < inicioHoy || d > finSemana) continue;
  eventos.push({ d, titulo: fm.titulo || f.nombre.replace(/\.md$/, '') });
}

eventos.sort((a, b) => a.d.toMillis() - b.d.toMillis());

const hoy = eventos.filter((e) => e.d <= finHoy);
const resto = eventos.filter((e) => e.d > finHoy);

const partes = ['Buenos días. Hoy es ' + DIAS[ahora.weekday - 1] + ' ' +
  ahora.day + ' de ' + MESES[ahora.month - 1] + '.'];

partes.push('');
if (hoy.length) {
  partes.push('Hoy:');
  for (const e of hoy) partes.push('- ' + e.d.toFormat('HH:mm') + '  ' + e.titulo);
} else {
  partes.push('Hoy no tienes nada apuntado.');
}

if (resto.length) {
  partes.push('');
  partes.push('Esta semana:');
  for (const e of resto) {
    partes.push('- ' + DIAS[e.d.weekday - 1] + ' ' + e.d.day + ', ' +
      e.d.toFormat('HH:mm') + '  ' + e.titulo);
  }
}

return [{ json: { chat_id: chat, texto: partes.join('\n') } }];
